def traffic_jam(main_road, side_streets):
    n = len(main_road)
    side_len = len(side_streets)
    for _ in range(n):
        for i in range(min(side_len, n)):
            if side_streets[i]:
                main_road = main_road[:i] + side_streets[i][-1] + main_road[i:]
                side_streets[i] = side_streets[i][:-1]
        main_road = main_road[:-1]
